  }

  function closeShopUI() {
    activeShopSession.shopkeeperId = 0;
    activeShopSession.mode = "browse";
    try { window.dispatchEvent(new CustomEvent("ui:closeShop")); } catch (e) { console.debug('[shopWiring] dispatch ui:closeShop:', e); }
  }

